'use strict';
(function(root){
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),key='walk-manual-damage-v7';
const fields={attack:'装備・こころ込みの表示攻撃力',defense:'敵の守備力',multiplier:'1発のスキル倍率（%）',hits:'同じ倍率のヒット数',attackStages:'攻撃力の段階（−3〜3）',defenseStages:'敵守備力の段階（−3〜3）',slash:'装備等の斬撃／体技ダメージ（%）',elementBonus:'装備等の属性ダメージ（%）',raceBonus:'装備等の系統特効（%）',nameBonus:'装備等の敵名特効（%）',skillBuff:'スキル威力・おうえん等の合計（%）',criticalBonus:'装備等の会心ダメージ加算（%）',criticalExtra:'魔人・こころ道等の会心加算（%）',criticalBoost:'会心のひらめき等の倍率',charge:'きあいため倍率',dualRate:'1発の二刀流係数（通常1／基本0.4）',allyTension:'味方テンションによる強化率（%）',enemyTension:'敵テンションによる強化率（%）',typeResistance:'敵の斬撃／体技耐性（%・弱点は負）',elementResistance:'敵の属性耐性（%・弱点は負）',forcedResistance:'領域等による属性耐性増減（%）',resistChange:'属性弱化・フォースブレイクの加算（%）',eradicate:'根絶やし等の系統特効増幅（%）',skillCorrection:'別枠のスキル倍率補正（%）',causality:'因果等の別枠倍率加算（%）',levelUp:'レベルアップ段数（0〜20）',levelDown:'敵レベルダウン段数（0〜10）',sword:'剣魔合一の加算値',elementBuff:'ゾーン等の属性バフ（%・通常フォース時のみ半減）',forceCharge:'フォースチャージの属性加算（%・段階×30）',forcedTypeResistance:'領域等による斬体耐性増減（%）',typeDebuff:'斬体の被ダメージ補正（%・耐性低下や衰弱等の同群合計）'};
function render({target,master}){
 let saved={};try{saved=JSON.parse(localStorage.getItem(key))||{};}catch{}const p={...PhysicalCalculator.defaults(),...saved},legacyResistance=saved.schemaVersion!==22&&Number(saved.resistChange)!==0&&saved.resistChange!=null;
 const field=k=>`<label>${fields[k]}<input name="${k}" type="number" step="any" required value="${Number.isFinite(p[k])?p[k]:PhysicalCalculator.defaults()[k]}"></label>`;
 const selects=[['weapon','武器'],['left','左手（能力値は表示攻撃力に含める）'],['head','頭'],['body','体上'],['legs','体下'],['shield','盾'],['accessory','アクセサリー1'],['accessory2','アクセサリー2'],['pearl','心珠1'],['pearl2','心珠2'],...Array.from({length:4},(_,i)=>['heart'+i,'こころ'+(i+1)])];
 target.innerHTML=`<h2>敵・装備・スキルを指定して火力を検証</h2><p>まず物理ダメージを独立して照合します。通常・直撃・会心・二刀流と補助状態を指定し、1発／合計の乱数範囲と計算内訳を確認できます。</p><div class="notice">物理式の検証版です。公開検証式との一致と、実ゲームの実測一致は別です。呪文・ブレス・攻魔複合の正確な対応と、参考記事の実測火力との一致は未完了です。自動選定は既存の試作として残しています。</div>${legacyResistance?'<p class="notice">旧入力の「斬体耐性低下」欄は内部で属性弱化として扱われていました。値は現在の属性弱化欄に保持しています。斬体の被ダメージ補正とは分けて確認してください。</p>':''}<details class="panel"><summary>数式検証の範囲と未検証事項</summary><p>2026-10-22：端数誤差を数値安定化した公開式モデルと1万条件を比較し、下限・上限の差分0。公開式そのままのJavaScriptとは、浮動小数点の境界処理を区別しています。</p><p>実機での照合例は未登録です。呪文・ブレス・攻魔複合、敵シールド、ダメージ上限、命中・ガード、未収録スキル固有効果の完全再現は未完了です。</p><a href="data/validation/physical.json" target="_blank">数式照合記録</a></details><form id="manual-form"><div class="details-grid"><section class="panel"><h3>敵とスキル</h3><label>敵名<input name="enemyName" maxlength="80" value="${esc(saved.enemyName||'任意の敵')}"></label><p class="muted">スキル名は記録用です。倍率・ヒット数・直撃・会心は下の欄で指定します。</p><label>スキル名<input name="skillName" maxlength="80" value="${esc(saved.skillName||'任意の物理スキル')}"></label>${['attack','defense','multiplier','hits','attackStages','defenseStages'].map(field).join('')}<label>会心種別<select name="criticalType">${[['normal','非会心'],['single','単発会心（1.6倍）'],['multi','多段会心（1.6〜2.0倍）'],['super','超会心（2.3〜2.7倍）']].map(([v,n])=>`<option value="${v}" ${p.criticalType===v?'selected':''}>${n}</option>`).join('')}</select></label><label><input type="checkbox" name="direct" ${p.direct?'checked':''}> 直撃（会心とは独立）</label><label><input type="checkbox" name="force" ${p.force?'checked':''}> フォースで属性ダメージ補正を半減</label></section><section class="panel"><h3>装備・こころと補助状態</h3><p>表示攻撃力には装備・こころを含めた実機の値を入力します。以下は特殊効果の合計です。自動発動する補助も、発動状態を明示して入力します。</p>${['slash','elementBonus','raceBonus','nameBonus','skillBuff','criticalBonus','criticalExtra','criticalBoost','charge','dualRate'].map(field).join('')}</section></div><details class="panel"><summary>敵耐性・テンション・個別効果</summary><div class="details-grid">${Object.keys(fields).slice(16).map(field).join('')}</div><p>敵耐性は40なら40%軽減、−20なら20%弱点です。領域による耐性低下は負で入力します。二刀流は1発の係数とヒット数をそれぞれ指定します。根絶やし300%は系統特効値を増幅し、攻撃全体を4倍にはしません。</p></details><details class="panel"><summary>使用装備を記録・特殊効果を読み込む</summary><p>収録された効果だけを読み込みます。職業限定効果や未収録の性能は実機の合計値で補正してください。左手は魔人の片手剣二刀流を想定します。装備能力値を表示攻撃力に再加算しません。</p><div class="details-grid">${selects.map(([s,n])=>{const slot=s==='left'?'weapon':s.startsWith('heart')?'heart':s.replace(/2$/,'');return `<label>${n}<select name="item-${s}"><option value="">未指定</option>${master.items.filter(i=>i.slot===slot&&i.ready&&(s!=='left'||i.weaponType==='片手剣')).map(i=>`<option value="${esc(i.id)}" ${saved['item-'+s]===i.id?'selected':''}>${esc(i.name)}${i.limitBreak!==undefined?' '+i.limitBreak+'凸':''}${i.verifiedModel?'':'（仮性能あり）'}</option>`).join('')}</select></label>`;}).join('')}<label>攻撃種別<select name="damageType"><option>斬撃</option><option ${saved.damageType==='体技'?'selected':''}>体技</option></select></label><label>攻撃属性<select name="element">${AutoDamage.elements.map(e=>`<option ${saved.element===e?'selected':''}>${e}</option>`).join('')}</select></label><label>敵の系統<input name="race" value="${esc(saved.race||'ドラゴン系')}"></label></div><button type="button" id="load-bonuses">収録された特殊効果を合計して入力欄へ反映</button><p id="equipment-note" role="status"></p></details><label>実測ダメージ（任意・合計）<input name="observed" type="number" min="0" max="100000000" step="1" value="${Number.isFinite(Number(saved.observed))?esc(saved.observed||''):''}"></label><div class="row padded"><button type="submit" class="primary">ダメージを計算する</button></div><p id="manual-status" role="status"></p></form><section id="manual-output" aria-live="polite"></section>`;
 const form=target.querySelector('form'),output=target.querySelector('#manual-output'),status=target.querySelector('#manual-status');
 const collect=()=>{const data=Object.fromEntries(new FormData(form));data.schemaVersion=22;data.schemaVersion=22;for(const k of Object.keys(fields))data[k]=Number(data[k]);for(const k of ['direct','force'])data[k]=form.elements[k].checked;return data;};
 form.oninput=()=>{output.innerHTML='';status.textContent='条件を変更しました。再計算してください。';};
 target.querySelector('#load-bonuses').onclick=()=>{const data=collect(),items=selects.map(([s])=>master.items.find(i=>i.id===data['item-'+s])).filter(Boolean);if(new Set(items.filter(i=>i.slot==='heart').map(i=>i.monster||i.name)).size<items.filter(i=>i.slot==='heart').length){status.textContent='同じ種類のこころを重複指定しています。';return;}const build={bonuses:items.flatMap(i=>i.bonuses||[])};for(const [k,g]of [['slash','general'],['elementBonus','element'],['raceBonus','race'],['criticalBonus','critical']])form.elements[k].value=Math.round(AutoDamage.sum(build,g,g==='critical'?null:data.damageType,data.element,data.race)*10000)/100;form.elements.nameBonus.value=0;output.innerHTML='';target.querySelector('#equipment-note').textContent=items.length+'点の収録効果を反映しました。未収録効果・職業固有効果・バフは別途入力してください。';};
 form.onsubmit=e=>{e.preventDefault();try{const data=collect();if(data['item-left']&&data['item-shield'])throw Error('二刀流と盾は同時に指定できません。');const hs=selects.filter(([s])=>s.startsWith('heart')).map(([s])=>master.items.find(i=>i.id===data['item-'+s])).filter(Boolean);if(new Set(hs.map(i=>i.monster||i.name)).size!==hs.length)throw Error('同じ種類のこころは重複指定できません。');const r=PhysicalCalculator.calculate({...data,includeTrace:true});localStorage.setItem(key,JSON.stringify(data));output.innerHTML=`<article class="panel"><h2>${esc(data.enemyName)}への ${esc(data.skillName)}</h2><p class="notice">合計 ${r.min.toLocaleString()} 〜 ${r.max.toLocaleString()} ダメージ</p><p>1発 ${r.hit.min.toLocaleString()} 〜 ${r.hit.max.toLocaleString()} × ${data.hits}発。命中・ガード等による失敗は含まない条件付きの範囲です。</p>${data.observed!==''?`<p>実測 ${Number(data.observed).toLocaleString()}：${Number(data.observed)>=r.min&&Number(data.observed)<=r.max?'計算範囲内です。':'計算範囲外です。未入力の効果・能力値・式を確認してください。'}</p>`:''}<p>属性弱化と斬体の被ダメージ補正は別の群です。属性弱化＋30%・斬体補正＋20%なら ×1.3×1.2。装備の属性UPや敵の元の耐性へ足しません。</p><details><summary>丸め段階の数値を確認</summary><p>下限：基礎乱数 ${r.hit.stages.min.base} → 第1段階 ${r.hit.stages.min.first} → ため等の第2段階 ${r.hit.stages.min.second} → 二刀流後 ${r.hit.stages.min.third}</p><p>上限：基礎乱数 ${r.hit.stages.max.base} → 第1段階 ${r.hit.stages.max.first} → ため等の第2段階 ${r.hit.stages.max.second} → 二刀流後 ${r.hit.stages.max.third}</p></details><h3>計算内訳</h3><p>補助後攻撃力 ${r.effectiveAttack} ／ 有効守備力 ${r.effectiveDefense} ／ 基礎値 ${r.hit.base}</p><p>テンション等適用後：斬体 ${r.corrections.slash}% ／ 属性 ${r.corrections.element}% ／ 系統 ${r.corrections.race}% ／ 名称 ${r.corrections.name}%</p><p>第1段階で基礎値・スキル・各群・会心を掛けて切り捨て → 別枠スキル補正ときあいためを掛けて切り捨て → 二刀流係数を掛けて切り上げ → ヒット数を乗算。</p><ul>${r.limits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><a href="${r.evidence}" target="_blank" rel="noreferrer">照合した公開検証式</a></p><details><summary>計算に使った値（記録用）</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">${esc(JSON.stringify(r,null,2))}</pre></details></article>`;status.textContent='計算条件をこのブラウザに保存しました。';}catch(err){output.innerHTML='';status.textContent=err.message;}};
}
root.CalculatorUI={render};
})(typeof window==='undefined'?globalThis:window);
